const binaryKeys = Object.keys($binary || {});

// Generate Unique Correlation Request ID: KRISHI-YYYYMMDD-XXXX
const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g, '');
const randStr = Math.random().toString(36).substring(2, 6).toUpperCase();
const requestId = `KRISHI-${dateStr}-${randStr}`;

// Canonical 75 Target Crops from KRISHI MARGA Master Catalogue
const TARGET_75_CROPS = [
  'paddy', 'maize', 'ragi', 'sorghum', 'pearl_millet', 'foxtail_millet', 'little_millet',
  'kodo_millet', 'barnyard_millet', 'proso_millet', 'wheat', 'red_gram', 'black_gram',
  'green_gram', 'bengal_gram', 'cowpea', 'field_bean', 'groundnut', 'sesame', 'sunflower',
  'castor', 'safflower', 'soybean', 'cotton', 'sugarcane', 'tobacco', 'tomato', 'chilli',
  'brinjal', 'onion', 'okra', 'potato', 'tapioca', 'sweet_potato', 'drumstick', 'cucumber',
  'pumpkin', 'bitter_gourd', 'bottle_gourd', 'ridge_gourd', 'beans', 'cabbage', 'cauliflower',
  'carrot', 'beetroot', 'banana', 'mango', 'papaya', 'pomegranate', 'guava', 'sapota',
  'pineapple', 'grapes', 'jackfruit', 'watermelon', 'muskmelon', 'citrus_lime', 'coconut',
  'arecanut', 'cashew', 'coffee', 'tea', 'rubber', 'cocoa', 'oil_palm', 'palmyrah',
  'black_pepper', 'cardamom', 'turmeric', 'ginger', 'clove', 'coriander', 'cumin',
  'fenugreek', 'betel_vine'
];

const CROP_ALIASES = {
  'rice': 'paddy',
  'dhan': 'paddy',
  'corn': 'maize',
  'chili': 'chilli',
  'pepper_bell': 'chilli',
  'capsicum': 'chilli',
  'acid_lime': 'citrus_lime',
  'lemon': 'citrus_lime',
  'lime': 'citrus_lime',
  'cassava': 'tapioca',
  'betel_nut': 'arecanut',
  'betel_leaf': 'betel_vine',
  'pigeon_pea': 'red_gram',
  'arhar': 'red_gram',
  'tur': 'red_gram',
  'mung_bean': 'green_gram',
  'moong': 'green_gram',
  'urad': 'black_gram',
  'chickpea': 'bengal_gram',
  'chana': 'bengal_gram',
  'grape': 'grapes',
  'black pepper': 'black_pepper',
  'pearl millet': 'pearl_millet',
  'foxtail millet': 'foxtail_millet',
  'little millet': 'little_millet',
  'kodo millet': 'kodo_millet',
  'barnyard millet': 'barnyard_millet',
  'proso millet': 'proso_millet',
  'red gram': 'red_gram',
  'black gram': 'black_gram',
  'green gram': 'green_gram',
  'bengal gram': 'bengal_gram',
  'field bean': 'field_bean',
  'sweet potato': 'sweet_potato',
  'bitter gourd': 'bitter_gourd',
  'bottle gourd': 'bottle_gourd',
  'ridge gourd': 'ridge_gourd',
  'oil palm': 'oil_palm',
  'betel vine': 'betel_vine'
};

// 1. Validate Image Count (1 to 10)
if (binaryKeys.length === 0) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'NO_IMAGES_UPLOADED',
      errorMessage: 'Please upload at least 1 image (up to 10 images supported).'
    }
  }];
}

if (binaryKeys.length > 10) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'TOO_MANY_IMAGES',
      errorMessage: 'Maximum 10 images allowed per diagnosis request. Please select between 1 and 10 photos.'
    }
  }];
}

// 2. Validate Selected Crop
const rawCrop = $json.body?.crop || $json.query?.crop || null;

if (!rawCrop || typeof rawCrop !== 'string' || rawCrop.trim() === '') {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'INVALID_CROP',
      errorMessage: 'Please select exactly one target crop for this diagnosis case.'
    }
  }];
}

const cropTrimmed = rawCrop.trim();
if (cropTrimmed.includes(',') || cropTrimmed.includes(';') || Array.isArray(rawCrop)) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'MULTIPLE_CROPS_NOT_SUPPORTED',
      errorMessage: 'Only one crop can be diagnosed per request. Please submit separate requests for different crops.'
    }
  }];
}

const normInput = cropTrimmed.toLowerCase().replace(/[\s\-_]+/g, '_');
const matchedCropId = TARGET_75_CROPS.find(c => c === normInput)
  || CROP_ALIASES[cropTrimmed.toLowerCase()]
  || CROP_ALIASES[normInput]
  || TARGET_75_CROPS.find(c => normInput.includes(c) || c.includes(normInput));

if (!matchedCropId) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'UNSUPPORTED_CROP',
      errorMessage: `Crop '${cropTrimmed}' is not in the 75 target crop catalogue. Please choose a valid target crop.`
    }
  }];
}


// Per-image size guard. Base64 expands a payload by ~33%, so a single very
// large photo can exhaust the workflow's memory. The mobile app already
// downsizes images; this is the server-side backstop.
const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
let totalBytes = 0;

// 3. Validate and Extract Binary Images
const imagesList = [];
for (let i = 0; i < binaryKeys.length; i++) {
  const key = binaryKeys[i];
  const bin = $binary[key];
  const mimeType = bin.mimeType || 'image/jpeg';

  if (!mimeType.startsWith('image/')) {
    return [{
      json: {
        requestId: requestId,
        isValid: false,
        errorCode: 'INVALID_FILE_TYPE',
        errorMessage: `File '${bin.fileName || key}' is not a supported image format (JPEG, PNG, WEBP).`
      }
    }];
  }

  let base64Data = '';
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    base64Data = buffer.toString('base64');
  } catch (e) {
    base64Data = bin.data || '';
  }

  if (!base64Data) {
    return [{
      json: {
        requestId: requestId,
        isValid: false,
        errorCode: 'UNREADABLE_IMAGE',
        errorMessage: `Image '${bin.fileName || key}' could not be read. Please retake the photo.`
      }
    }];
  }

  const approxBytes = Math.floor(base64Data.length * 0.75);
  if (approxBytes > MAX_IMAGE_BYTES) {
    return [{
      json: {
        requestId: requestId,
        isValid: false,
        errorCode: 'IMAGE_TOO_LARGE',
        errorMessage: 'One of the photos is too large. Please retake it at a lower resolution.'
      }
    }];
  }
  totalBytes += approxBytes;

  if (totalBytes > 12 * 1024 * 1024) {
    return [{
      json: {
        requestId: requestId,
        isValid: false,
        errorCode: 'PAYLOAD_TOO_LARGE',
        errorMessage: 'The combined photo size is too large. Please send fewer photos.'
      }
    }];
  }

  imagesList.push({
    mimeType: mimeType,
    data: base64Data,
    fileName: bin.fileName || `image_${i+1}.jpg`
  });
}

// 4. Extract and Map Language
const langMap = {
  'en': 'English',
  'kn': 'Kannada',
  'ta': 'Tamil',
  'te': 'Telugu',
  'ml': 'Malayalam',
  'hi': 'Hindi'
};
const rawLang = String($json.body?.language || $json.query?.language || 'en').toLowerCase().trim();
const languageCode = langMap[rawLang] ? rawLang : (Object.keys(langMap).find(k => langMap[k].toLowerCase() === rawLang) || 'en');
const requestedLanguage = langMap[languageCode] || 'English';

const symptoms = $json.body?.symptoms || $json.body?.farmer_notes || $json.query?.symptoms || null;
const latitude = $json.body?.latitude || $json.query?.latitude || null;
const longitude = $json.body?.longitude || $json.query?.longitude || null;
const state = $json.body?.state || 'South India';

// 5. Pre-build Dynamic Crop-Specific Gemini Multimodal Payload
const promptText = `Expert Plant Pathologist and Agronomist AI for Indian agriculture.
You are diagnosing a ${cropTrimmed.toUpperCase()} plant.
Analyze only the uploaded ${cropTrimmed} plant images.
Consider diseases, pests and visible nutrient-related symptoms relevant to ${cropTrimmed}.
Do not diagnose a disease belonging to another crop.

CASE CONTEXT:
- Selected Crop: "${cropTrimmed}"
- Images Provided: ${imagesList.length}
${symptoms ? `- Farmer Stated Symptoms: "${symptoms}"\n` : ''}- Target Response Language: ${requestedLanguage} (Language Code: ${languageCode})

CRITICAL DIAGNOSIS RULES:
1. WRONG CROP PROTECTION (MANDATORY):
- Carefully verify if the uploaded plant image actually matches ${cropTrimmed}.
- If the image clearly depicts a DIFFERENT crop (for example, tomato when coffee was selected, or chilli when banana was selected, or non-plant objects):
  * Do NOT diagnose another crop's disease on ${cropTrimmed}!
  * Set: health_status = "Uncertain", disease = "Unknown", confidence = 0.20, problem_type = "UNKNOWN"
  * In user_message (${requestedLanguage}): State clearly: "The image does not appear to match the selected crop (${cropTrimmed}). Please upload a clear ${cropTrimmed} plant image."

2. BLURRY / LOW-QUALITY / NON-PLANT / INSUFFICIENT EVIDENCE:
- If photos are blurry, too dark, out of focus, or lack clear symptoms:
  * Do NOT fabricate a diagnosis or pretend certainty.
  * Set: health_status = "Uncertain", disease = "Unknown", confidence = 0.25, problem_type = "UNKNOWN"
  * In user_message (${requestedLanguage}): Advise the farmer to take a closer, clearer photo in good daylight.

3. HEALTHY PLANTS:
- If the ${cropTrimmed} foliage and plant parts show normal green color, intact tissue, and no signs of pest or pathogen:
  * Set: health_status = "Healthy", disease = "None", confidence = 0.95, severity = "None", problem_type = "HEALTHY"
  * In recommendations and user_message (${requestedLanguage}): Provide maintenance care and fertilization advice for healthy ${cropTrimmed}.

4. PROBLEM IDENTIFICATION (DISEASE, PEST, OR NUTRIENT DEFICIENCY):
- Identify the problem accurately:
  * problem_type: MUST be one of ["DISEASE", "PEST", "NUTRIENT_DEFICIENCY", "HEALTHY", "UNKNOWN"]
  * disease: The specific disease, pest, or nutrient deficiency name in ${requestedLanguage}
  * confidence: Realistic score between 0.50 and 0.98 based on visible evidence
  * severity: "Mild" | "Moderate" | "Severe" | "None"
  * symptoms: Array of observed visual symptoms in ${requestedLanguage}
  * recommendations: Practical actionable agronomic steps in ${requestedLanguage}
  * prevention: Practical prevention and cultural steps in ${requestedLanguage}
  * regional_advice: Practical advice for South Indian farmers in ${requestedLanguage}
  * user_message: Direct message to the farmer in ${requestedLanguage}

5. PESTICIDE & CHEMICAL SAFETY (STRICT):
- Never invent a disease, pesticide brand, active ingredient, or unverified chemical dosage.
- If verified chemical dosage is unavailable, advise consulting the local agricultural extension officer or Krishi Vigyan Kendra (KVK).
- Prioritize integrated pest management (IPM), cultural sanitation, and approved biocontrol methods (Trichoderma, Pseudomonas, Neem).

MANDATORY OUTPUT REQUIREMENT:
Return ONLY valid JSON with keys in English and natural language values in ${requestedLanguage}:
{
  "crop": "${cropTrimmed}",
  "health_status": "Healthy",
  "disease": "None",
  "confidence": 0.95,
  "severity": "None",
  "problem_type": "HEALTHY",
  "symptoms": ["..."],
  "recommendations": ["..."],
  "prevention": ["..."],
  "regional_advice": "...",
  "user_message": "..."
}`;

const imageParts = imagesList.map(img => ({
  inlineData: {
    mimeType: img.mimeType || 'image/jpeg',
    data: img.data
  }
}));

const geminiPayload = {
  contents: [
    {
      parts: [
        { text: promptText },
        ...imageParts
      ]
    }
  ],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.0,
    seed: 42
  }
};

return [{
  json: {
    requestId: requestId,
    isValid: true,
    crop: cropTrimmed,
    cropCanonicalId: matchedCropId,
    imageCount: imagesList.length,
    symptoms: symptoms,
    language: languageCode,
    requestedLanguage: requestedLanguage,
    latitude: latitude,
    longitude: longitude,
    state: state,
    geminiPayload: geminiPayload,
    startedAt: Date.now()
  }
}];

const res = $json || {};

// The HTTP node is configured to continue on error, so this item may contain
// an error envelope instead of a Gemini response. Treat that as "not usable"
// and let the failover chain proceed.
if (res.error || res.errorMessage || res.__isError) {
  return [{ json: { is_usable: false, error_reason: 'MODEL_CALL_FAILED' } }];
}

try {
  if (res.error || !res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (!parsed.crop || !parsed.health_status || parsed.confidence === undefined) {
    return [{ json: { is_usable: false, error_reason: 'MISSING_REQUIRED_FIELDS' } }];
  }

  // Clamp confidence between 0 and 1
  let conf = parsed.confidence;
  if (typeof conf !== 'number') conf = Number(conf) || 0;
  if (conf < 0) conf = 0;
  if (conf > 1) conf = 1;
  parsed.confidence = conf;

  return [{ json: { is_usable: true, model_used: 'Gemini 3.5 Flash Lite', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message } }];
}

const res = $json || {};

// The HTTP node is configured to continue on error, so this item may contain
// an error envelope instead of a Gemini response. Treat that as "not usable"
// and let the failover chain proceed.
if (res.error || res.errorMessage || res.__isError) {
  return [{ json: { is_usable: false, error_reason: 'MODEL_CALL_FAILED' } }];
}

try {
  if (res.error || !res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (!parsed.crop || !parsed.health_status || parsed.confidence === undefined) {
    return [{ json: { is_usable: false, error_reason: 'MISSING_REQUIRED_FIELDS' } }];
  }

  return [{ json: { is_usable: true, model_used: 'Gemini 3.6 Flash', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message } }];
}

const res = $json || {};

// The HTTP node is configured to continue on error, so this item may contain
// an error envelope instead of a Gemini response. Treat that as "not usable"
// and let the failover chain proceed.
if (res.error || res.errorMessage || res.__isError) {
  return [{ json: { is_usable: false, error_reason: 'MODEL_CALL_FAILED' } }];
}

try {
  if (res.error || !res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (!parsed.crop || !parsed.health_status || parsed.confidence === undefined) {
    return [{ json: { is_usable: false, error_reason: 'MISSING_REQUIRED_FIELDS' } }];
  }

  return [{ json: { is_usable: true, model_used: 'Gemini 2.5 Pro', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message } }];
}

const data = ($json && $json.parsed_data) ? $json.parsed_data : null;
let inputMeta = {};
try {
  inputMeta = $('2. Validate Input & Crop').item.json || {};
} catch (e) {
  inputMeta = {};
}

if (!data) {
  return [{
    json: {
      requestId: inputMeta.requestId || `KRISHI-${Date.now()}`,
      success: false,
      errorCode: 'DIAGNOSIS_FAILED',
      message: 'Online diagnosis could not be completed.'
    }
  }];
}

let confidenceLevel = 'High';
let healthStatus = data.health_status || 'Uncertain';

const confNum = typeof data.confidence === 'number' ? data.confidence : Number(data.confidence || 0);
if (confNum < 0.50) {
  confidenceLevel = 'Low';
  healthStatus = 'Uncertain';
} else if (confNum < 0.75) {
  confidenceLevel = 'Medium';
}

const problemType = data.problem_type || (
  healthStatus === 'Healthy' ? 'HEALTHY' :
  (healthStatus === 'Uncertain' ? 'UNKNOWN' : 'DISEASE')
);

return [{
  json: {
    requestId: inputMeta.requestId || `KRISHI-${Date.now()}`,
    success: true,
    timestamp: new Date().toISOString(),
    crop_selected: inputMeta.crop || data.crop || 'Unknown',
    images_analyzed: inputMeta.imageCount || 1,
    model_provider: $json.model_used || 'Gemini 3.5 Flash Lite',
    latency_ms: inputMeta.startedAt ? (Date.now() - inputMeta.startedAt) : undefined,
    result: {
      crop: data.crop || inputMeta.crop || 'Unknown',
      health_status: healthStatus,
      disease: data.disease || (healthStatus === 'Healthy' ? 'None' : 'Unknown'),
      confidence: confNum,
      confidence_level: confidenceLevel,
      severity: data.severity || 'None',
      problem_type: problemType,
      symptoms: Array.isArray(data.symptoms) ? data.symptoms : (data.symptoms ? [data.symptoms] : []),
      recommendations: Array.isArray(data.recommendations) ? data.recommendations : (data.recommendations ? [data.recommendations] : []),
      prevention: Array.isArray(data.prevention) ? data.prevention : (data.prevention ? [data.prevention] : []),
      regional_advice: data.regional_advice || '',
      user_message: data.user_message || '',
      location_context: {
        state: inputMeta.state || 'South India',
        latitude: inputMeta.latitude || null,
        longitude: inputMeta.longitude || null
      }
    }
  }
}];

const errCode = $json.errorCode || 'INVALID_REQUEST';
const errMsg = $json.errorMessage || 'Invalid request parameters';
return [{ json: { success: false, errorCode: errCode, message: errMsg, requestId: $json.requestId || null } }];

// PESTICIDE LABEL SCAN — INPUT VALIDATION
// Mirrors the disease branch, but validates a pesticide label request instead
// of a crop. Sending a pesticide scan to the crop-disease validator previously
// failed with INVALID_CROP, which is why label scanning never worked.

const binaryKeys = Object.keys($binary || {});

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const randStr = Math.random().toString(36).substring(2, 6).toUpperCase();
const requestId = `KRISHI-PEST-${dateStr}-${randStr}`;

const MAX_IMAGES = 3;
const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

if (binaryKeys.length === 0) {
  return [{ json: { requestId, isValid: false, errorCode: 'NO_IMAGES_UPLOADED', errorMessage: 'Please upload at least one photo of the pesticide label.' } }];
}

if (binaryKeys.length > MAX_IMAGES) {
  return [{ json: { requestId, isValid: false, errorCode: 'TOO_MANY_IMAGES', errorMessage: 'Please send at most 3 label photos (front, back, dosage panel).' } }];
}

const langMap = { en: 'English', kn: 'Kannada', ta: 'Tamil', te: 'Telugu', ml: 'Malayalam', hi: 'Hindi' };
const rawLang = String($json.body?.language || $json.query?.language || 'en').toLowerCase().trim();
const languageCode = langMap[rawLang] ? rawLang : 'en';
const requestedLanguage = langMap[languageCode];

const cropContext = ($json.body?.crop || $json.query?.crop || '').toString().trim();

const imagesList = [];
let totalBytes = 0;

for (let i = 0; i < binaryKeys.length; i++) {
  const key = binaryKeys[i];
  const bin = $binary[key];
  const mimeType = bin.mimeType || 'image/jpeg';

  if (!mimeType.startsWith('image/')) {
    return [{ json: { requestId, isValid: false, errorCode: 'INVALID_FILE_TYPE', errorMessage: `File '${bin.fileName || key}' is not a supported image (JPEG, PNG, WEBP).` } }];
  }

  let base64Data = '';
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    base64Data = buffer.toString('base64');
  } catch (e) {
    base64Data = bin.data || '';
  }

  if (!base64Data) {
    return [{ json: { requestId, isValid: false, errorCode: 'UNREADABLE_IMAGE', errorMessage: 'A label photo could not be read. Please retake it.' } }];
  }

  const approxBytes = Math.floor(base64Data.length * 0.75);
  if (approxBytes > MAX_IMAGE_BYTES) {
    return [{ json: { requestId, isValid: false, errorCode: 'IMAGE_TOO_LARGE', errorMessage: 'The label photo is too large. Please retake it at a lower resolution.' } }];
  }
  totalBytes += approxBytes;

  imagesList.push({ mimeType, data: base64Data, fileName: bin.fileName || `label_${i + 1}.jpg` });
}

const promptText = `You are an agricultural input label reader for Indian farmers.
Read ONLY what is actually printed on the pesticide/agro-chemical label in the photographs.

STRICT RULES:
1. Do NOT invent a product name, active ingredient, manufacturer, registration status, dosage, or safety instruction. If something is not legible on the label, leave that field null or an empty array.
2. Do NOT state a dosage unless the number and unit are clearly printed on the label. Otherwise leave dosage_notice empty and the app will tell the farmer to read the printed label.
3. If the photo is blurry, cropped, glared, or is not an agro-chemical label, set identified = false and explain why in unidentified_reason.
4. Safety guidance must be taken from the label text (or standard pictograms shown on it). Never generalise from memory of a similar product.
5. Report banned status only if the label or the printed CIBRC registration clearly indicates it; otherwise set is_banned to false and cibrc_registered to whether a registration number is visible.

${cropContext ? `The farmer intends to use this on: ${cropContext}. Only comment on suitability if the label lists crops.` : ''}
Write natural-language values in ${requestedLanguage}. Keep JSON keys in English.

Return ONLY valid JSON:
{
  "identified": true,
  "confidence": 0.0,
  "unidentified_reason": null,
  "product_name": null,
  "active_ingredient": null,
  "formulation": null,
  "category": null,
  "manufacturer": null,
  "cibrc_registered": false,
  "is_banned": false,
  "what_it_is": "",
  "general_use": "",
  "why_farmers_use_it": "",
  "target_pests": [],
  "suitable_crops": [],
  "safety_guidance": [],
  "dosage_notice": "",
  "user_message": "",
  "guidance": []
}`;

const geminiPayload = {
  contents: [
    {
      parts: [
        { text: promptText },
        ...imagesList.map((img) => ({ inlineData: { mimeType: img.mimeType, data: img.data } }))
      ]
    }
  ],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.0, seed: 42 }
};

return [{
  json: {
    requestId,
    isValid: true,
    scanType: 'pesticide',
    crop: cropContext || null,
    imageCount: imagesList.length,
    language: languageCode,
    requestedLanguage,
    geminiPayload,
    startedAt: Date.now()
  }
}];

const res = $json || {};

if (res.error || res.errorMessage || res.__isError) {
  return [{ json: { is_usable: false, error_reason: 'MODEL_CALL_FAILED' } }];
}

try {
  if (!res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  if (parsed.identified === undefined) {
    return [{ json: { is_usable: false, error_reason: 'MISSING_REQUIRED_FIELDS' } }];
  }

  let conf = typeof parsed.confidence === 'number' ? parsed.confidence : Number(parsed.confidence) || 0;
  if (conf < 0) conf = 0;
  if (conf > 1) conf = 1;
  parsed.confidence = conf;

  return [{ json: { is_usable: true, model_used: 'Gemini Vision (primary)', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message } }];
}

// Shapes the label-reading result into the envelope the mobile app expects.
// Nothing is substituted or invented here: a field the model could not read
// stays null/empty and the app falls back to the bundled CIBRC directory.

const item = $json || {};
let inputMeta = {};
try {
  inputMeta = $('2P. Validate Pesticide Request').item.json || {};
} catch (e) {
  inputMeta = {};
}

const data = item.parsed_data || null;

if (!data) {
  return [{
    json: {
      requestId: inputMeta.requestId || `KRISHI-PEST-${Date.now()}`,
      success: false,
      errorCode: 'LABEL_SCAN_FAILED',
      message: 'The pesticide label could not be analysed. Please retake the photo in good light.'
    }
  }];
}

const arr = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string' && x.trim()) : []);

return [{
  json: {
    requestId: inputMeta.requestId || `KRISHI-PEST-${Date.now()}`,
    success: true,
    scan_type: 'pesticide',
    timestamp: new Date().toISOString(),
    images_analyzed: inputMeta.imageCount || 1,
    model_provider: item.model_used || 'Gemini Vision',
    latency_ms: inputMeta.startedAt ? (Date.now() - inputMeta.startedAt) : undefined,
    result: {
      identified: Boolean(data.identified),
      confidence: typeof data.confidence === 'number' ? data.confidence : 0,
      unidentified_reason: data.unidentified_reason || null,
      product_name: data.product_name || null,
      active_ingredient: data.active_ingredient || null,
      formulation: data.formulation || null,
      category: data.category || null,
      manufacturer: data.manufacturer || null,
      cibrc_registered: Boolean(data.cibrc_registered),
      is_banned: Boolean(data.is_banned),
      what_it_is: data.what_it_is || '',
      general_use: data.general_use || '',
      why_farmers_use_it: data.why_farmers_use_it || '',
      target_pests: arr(data.target_pests),
      suitable_crops: arr(data.suitable_crops),
      safety_guidance: arr(data.safety_guidance),
      dosage_notice: data.dosage_notice || '',
      user_message: data.user_message || '',
      guidance: arr(data.guidance),
      crop_context: inputMeta.crop || null
    }
  }
}];

return [{
  json: {
    success: false,
    scan_type: 'pesticide',
    errorCode: $json.errorCode || 'INVALID_REQUEST',
    message: $json.errorMessage || 'The label scan request was not valid.',
    requestId: $json.requestId || null
  }
}];
